(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(w1x*0.03+y*0.01+t*0.15)*8;
  const w2y = Math.cos(w1y*0.03-x*0.01+t*0.2)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75)*40,0.085,1.8],
    [200+Math.sin(t*0.25+4)*110,220+Math.cos(t*0.45+3)*70,0.075,2.4],
    [300+Math.cos(t*0.7+1)*80,30+Math.sin(t*0.5+2)*50,0.095,2.0]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS+=Math.sin(d*f*0.5-t*sp*0.3+3)*Math.cos(d*f*0.3+t*sp*0.4);
  }
  const n=src.length,act=aS/n,inh=iS/n,harm=hS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15+Math.sin(sx*0.02-sy*0.03+t*0.5)*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2-t*0.8)*0.2+Math.sin(dist*0.03+ang*6-t*2)*0.15;
  const rd1=act-inh*0.7+bg*0.3+spiral;
  const rd2=harm*0.5+Math.sin(act*inh)*0.3+Math.cos(dist*0.06-t)*0.2;
  const reaction=Math.tanh(rd1*2.2+rd2*0.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-t*0.7)*Math.cos(sy*0.18+t*0.5)*0.3)*1.5)*0.3;
  const moire=Math.sin(sx*0.25)*Math.sin(sy*0.25)*Math.sin((sx-sy)*0.15+t)*0.15;
  const blend=reaction*0.6+cell*0.2+moire*0.1+spiral*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,90,120],[25,140,130],[120,175,100],[200,190,80],[220,150,70],[210,100,65],[180,60,70],[120,35,65],[60,20,55],[20,12,50],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15,edge=0.9+Math.pow(Math.abs(reaction),1.5)*0.25;
  const glow=Math.max(0,1-Math.abs(reaction)*0.8)*0.1;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*60)|0)
  ];
}
